-- language.sql: the tables the policy language page's example (docs/reference/language.md) reads, with the rows
-- its `test` lines check, so that tests/reference.sh applies the example and runs its tests.
--   Acme (org 1): carol (3) owns Plans; alice (1) is an admin
--   Plans (folder 1), owner carol
--   └── Board (folder 2), owner alice, inherit off: carol may view what is inside, not edit or share it
--       └── minutes.md (file 11), owner alice
\set ON_ERROR_STOP on
SET client_min_messages = warning;

DO $$ BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'app_user') THEN
    CREATE ROLE app_user NOLOGIN;
  END IF;
END $$;

CREATE SCHEMA app;

CREATE TABLE app.users (
  id     bigint  PRIMARY KEY,
  name   text    NOT NULL,
  active boolean NOT NULL DEFAULT true
);
CREATE TABLE app.orgs (
  id   bigint PRIMARY KEY,
  name text   NOT NULL
);
CREATE TABLE app.org_members (
  org_id  bigint NOT NULL REFERENCES app.orgs,
  user_id bigint NOT NULL REFERENCES app.users,
  role    text   NOT NULL CHECK (role IN ('admin', 'member')),
  PRIMARY KEY (org_id, user_id)
);
CREATE TABLE app.teams (
  id        bigint PRIMARY KEY,
  parent_id bigint REFERENCES app.teams,
  name      text   NOT NULL
);
CREATE TABLE app.team_members (
  team_id bigint NOT NULL REFERENCES app.teams,
  user_id bigint NOT NULL REFERENCES app.users,
  PRIMARY KEY (team_id, user_id)
);
CREATE TABLE app.projects (
  id       bigint PRIMARY KEY,
  owner_id bigint REFERENCES app.users,
  name     text   NOT NULL
);
CREATE TABLE app.folders (
  id          bigint  GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  org_id      bigint  NOT NULL REFERENCES app.orgs,
  parent_type text    CHECK (parent_type IN ('folder', 'project')),
  parent_id   bigint,
  owner_id    bigint  REFERENCES app.users,
  name        text    NOT NULL,
  inherit     boolean NOT NULL DEFAULT true,
  locked      boolean NOT NULL DEFAULT false,
  archived    boolean NOT NULL DEFAULT false
);
CREATE TABLE app.folder_links (
  folder_id bigint NOT NULL REFERENCES app.folders,
  parent_id bigint NOT NULL REFERENCES app.folders,
  PRIMARY KEY (folder_id, parent_id)
);
CREATE TABLE app.files (
  id           bigint  GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  folder_id    bigint  NOT NULL REFERENCES app.folders,
  owner_id     bigint  REFERENCES app.users,
  name         text    NOT NULL,
  confidential boolean NOT NULL DEFAULT false,
  body         text
);

GRANT USAGE ON SCHEMA app TO app_user;
GRANT SELECT ON ALL TABLES IN SCHEMA app TO app_user;
GRANT INSERT, UPDATE, DELETE ON app.folders, app.files TO app_user;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA app TO app_user;

INSERT INTO app.users (id, name) VALUES (1, 'alice'), (3, 'carol'), (7, 'gina');
INSERT INTO app.orgs VALUES (1, 'Acme');
INSERT INTO app.org_members VALUES (1, 1, 'admin'), (1, 3, 'member'), (1, 7, 'member');
INSERT INTO app.folders (id, org_id, parent_type, parent_id, owner_id, name, inherit) VALUES
  (1, 1, NULL, NULL, 3, 'Plans', true),
  (2, 1, 'folder', 1, 1, 'Board', false);
INSERT INTO app.files (id, folder_id, owner_id, name) VALUES (11, 2, 1, 'minutes.md');
DO $$ BEGIN
  PERFORM setval(pg_get_serial_sequence('app.folders', 'id'), 100);
  PERFORM setval(pg_get_serial_sequence('app.files', 'id'), 100);
END $$;
